        U,s,Wt=np.linalg.svd(d(m),full_matrices=False)
        for i in range(K): readers.append((l,nm,i,s[i],Din*Wt[i]))
    for m,nm in (("mlp.gate_proj","gate"),("mlp.up_proj","up")):
        U,s,Wt=np.linalg.svd(d(m),full_matrices=False)
        for i in range(K): readers.append((l,nm,i,s[i],Dpf*Wt[i]))
